import{z as A,x as p,o as l,c as d,q as i,j as o,D as E,d as t,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"LER 的 PSD 分析","description":"","frontmatter":{"title":"LER 的 PSD 分析","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ler-psd.md","filePath":"litho/ler-psd.md","lastUpdated":1791413859000}'),B={name:"litho/ler-psd.md"};function D(h,a,S,f,m,u){const r=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=i('<h1 id="ler-的-psd-分析" tabindex="-1">LER 的 PSD 分析 <a class="header-anchor" href="#ler-的-psd-分析" aria-label="Permalink to &quot;LER 的 PSD 分析&quot;">​</a></h1><div class="epigraph"><p>一个 $3\\sigma$ 把所有频率捆死。功率谱才问：毛边是剂量低频、化学核，还是 SEM 白噪声。</p><footer>—— 据 Constantoudis / Patsis 与 Naulleau 对 LER 功率谱的公开方法；Mack 对频谱分段的讨论</footer></div><p><a href="/litho/stochastic-monte-carlo">上一课</a>给出边的许多次实现。<a href="/litho/acid-diffusion-lwr">酸扩散与 LWR</a> 与 <a href="/litho/lwr-lcdu">LWR/LCDU</a> 已经警告不要只报一个纳米数。缺口是把沿边位置序列做成功率谱密度（PSD），并规定怎么读。相关长度作为谱的一个参数，留给<a href="/litho/ler-correlation-length">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>沿设计边取样 \\(x(y)\\)，去均值后做功率谱 \\(S(f)\\)。低频（长程）常来自剂量、flare、掩模、扫描；中频常含化学与电子核；高频被核压掉，又被 SEM 噪声抬起。积分 \\(S(f)\\) 在一定频窗内得到协议 LER——窗一改，数就改。ITRS 类协议要声明线长与滤波，本课指出物理原因：不同频段对应不同执行器。</p><p><span class="marginnote">术语翻译：功率谱密度（PSD）就是把粗糙的边拆成不同空间频率的正弦波，看每个频率分到多少「粗糙度能量」。横轴是频率（每纳米摆几次），曲线下的面积正比 LER 的平方——所以积分窗一挪，边界就跟着挪。</span></p><p>缺口不是再定义 LER，而是：MC 或实验必须交谱，才能判断上一课的核有没有抽对。只拟合 \\(3\\sigma\\)，可以把电子核、酸核、SEM 噪声调成同一积分。</p><h3 id="谱不是光学-mtf" tabindex="-1">谱不是光学 MTF <a class="header-anchor" href="#谱不是光学-mtf" aria-label="Permalink to &quot;谱不是光学 MTF&quot;">​</a></h3><p>光学传递函数作用在空中像上。LER 的 PSD 是边位置过程的谱。两者通过 NILS 耦合：光学调制差，同一化学噪声在边上放大，整张 \\(S(f)\\) 抬高，形状仍由核与相关决定。不要把 LER 谱的截止频率写成镜头 NA。</p><p><span class="marginnote">常见误区：初学者容易以为 LER 谱的高频截止由镜头 NA 决定，实际上那是化学/电子模糊核与 SEM 噪声的战场；NA 决定的是像的对比，只通过 NILS 影响谱的幅度，不管谱的形状。</span></p><p><span class="marginnote">自仿射模型常用 \\(S(f)\\propto 1/(1+(f\\xi)^2)^{\\alpha+1/2}\\) 一类，三个参数：幅度、相关长度 \\(\\xi\\)、粗糙指数。本课先钉 PSD 是接口；\\(\\xi\\) 下一课展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：CD-SEM 沿边密采样，多条线、多视场平均 \\(S(f)\\)，减仪器噪声（重复扫描同一边）。比较：只改 PEB，看中高频是否掉；只改剂量，看整体是否按 \\(1/N\\) 降；只改掩模批次，看低频是否钉死。MC：对每个实现算谱再平均，应与实验同一频窗。</p><p><a href="/litho/lwr-lcdu">LWR 与 LCDU</a> 的分工：PSD 主要服务长边；孔用 LCDU 与失效，不硬做「孔的 LER 谱」。</p>',14)),(l(),o(n,null,{default:E(()=>[s(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22%E8%BE%B9%E5%BA%8F%E5%88%97%20x(y)%22%5D%20--%3E%20PSD%5B%22S(f)%22%5D%0A%20%20PSD%20--%3E%20LOW%5B%22%E4%BD%8E%E9%A2%91%3A%20%E5%89%82%E9%87%8F%20%2F%20%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20PSD%20--%3E%20MID%5B%22%E4%B8%AD%E9%A2%91%3A%20%E5%8C%96%E5%AD%A6%20%2F%20%E7%94%B5%E5%AD%90%E6%A0%B8%22%5D%0A%20%20PSD%20--%3E%20HIGH%5B%22%E9%AB%98%E9%A2%91%3A%20%E6%A0%B8%E6%88%AA%E6%AD%A2%20%2F%20SEM%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"线性化图像：边位移 \\(\\approx\\) 噪声场 / 当地斜率。噪声场的相关函数是核的自卷积一类，傅里叶后就是 \\(S(f)\\) 的形状；斜率是 ILS，决定幅度。酸扩散低通，砍高 \\(f\\)；电子核同样，截止频率更高或相当，视材料。剂量均匀性几乎是 \\(f\\to 0\\) 的 \\(\\delta\\)，线长不够时漏进「LER」。",-1)),a[5]||(a[5]=e("p",null,"Naulleau 等用谱把光子项（随剂量降、形状受核约束）与掩模项（不随剂量降）分开。这是随机预算的计量，不是学术装饰。",-1)),(l(),o(n,null,{default:E(()=>[s(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E5%99%AA%E5%A3%B0%E5%9C%BA%20(%E5%85%89%E5%AD%90%20%2F%20%E9%85%B8%20%2F%20%E7%94%B5%E5%AD%90)%22%5D%20--%3E%20CORR%5B%22%E7%9B%B8%E5%85%B3%E5%87%BD%E6%95%B0%20%3D%20%E6%A0%B8%E7%9A%84%E8%87%AA%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20CORR%20--%3E%7C%22%E5%82%85%E9%87%8C%E5%8F%B6%E5%8F%98%E6%8D%A2%22%7C%20SHAPE%5B%22%E5%AE%9A%E4%B8%8B%20S(f)%20%E7%9A%84%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20ILS%5B%22%E5%9B%BE%E5%83%8F%E5%AF%B9%E6%95%B0%E6%96%9C%E7%8E%87%20ILS%22%5D%20--%3E%20AMP%5B%22%E6%8A%AC%E5%8D%87%20S(f)%20%E7%9A%84%E5%B9%85%E5%BA%A6%22%5D%0A%20%20DOSE%5B%22%E5%89%82%E9%87%8F%E5%9D%87%E5%8C%80%E6%80%A7%20(f%20%E8%B6%8B%E9%9B%B6)%22%5D%20--%3E%20MIX%5B%22%E7%BA%BF%E9%95%BF%E4%B8%8D%E8%B6%B3%E6%97%B6%E6%B7%B7%E8%BF%9B%20LER%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：若把积分窗的高频端从 \\(2\\ \\mathrm{nm}^{-1}\\) 收到 \\(1\\ \\mathrm{nm}^{-1}\\)，等于不再统计波长小于 1 nm 的毛刺，报出的 LER 会凭空变小——两家实验室窗不同，同一片晶圆也能差出可观的比例，这就是「窗必须声明」的代价。</span></p><p><span class="marginnote">刻蚀转移是另一道滤波，ADI 与 AEI 的 PSD 不同。必须声明。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某篇会议的 \\(\\alpha=0.8\\) 写成所有层。不发明谱仪型号。下一课把 \\(\\xi\\) 从这张谱里读出，并解释为何低频粗糙特别伤器件。SEM 收缩对细线谱的污染，计量课再写；本课要求报谱时声明是否校正。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PSD 把 LER 按频率拆给不同执行器；积分窗必须声明。</li><li>幅度乘光学 ILS；形状乘化学/电子核；低频常非胶。</li><li>MC 只拟合 \\(3\\sigma\\) 不够，必须对谱。</li><li>ADI/AEI 谱不同。</li><li>出处：Constantoudis 等 LER 谱方法；Naulleau 用谱拆光子与掩模；Mack。</li></ul>',6))])}const c=A(B,[["render",D]]);export{P as __pageData,c as default};
